            THomeworkModel tHomeworkModel = new THomeworkModel(exam.getCourseId(), 0, 1, "历史作业", 2, 1, new Date(), 3);
            homeworkModelService.save(tHomeworkModel);
            cacheId.put(exam.getCourseId(), tHomeworkModel.getId());
        });
    }

