        InputStream inputStream = new FileInputStream(filePath);

        try {
            if (filePath.endsWith(EXCEL_XLS)) {
                return new HSSFWorkbook(inputStream);
            } else {
                return new XSSFWorkbook(inputStream);
            }
        } catch (Exception e) {
            throw new Exception(e);
        } finally {
            inputStream.close();
        }

    }

