            return;
        }
        UserInfo user = userInfoService.getById(userId);
        //学生作业表集合
        List<TStuHomework> stuHomeworkList = new ArrayList<>();
        //学生作业明细表集合
        List<TStuHomeworkInfo> tStuHomeworkInfos = new ArrayList<>();
        homeworkDistributions.forEach(item -> {
