                                    catalogueProcess.setDeleteFlag(0);
                                }
                                tCatalogueProcesses.add(catalogueProcess);
                            })
                    );
                }

            }

        }
        if (!tCatalogueProcesses.isEmpty()) {
            catalogueProcessService.saveOrUpdateBatch(tCatalogueProcesses);
        }
    }

