    private void reproduceExerciseInfos(TNewExercise exercise, int exerciseId, UserInfo loginUser) {
        //查询原始习题明细
        List<TExerciseInfo> infos = exerciseInfoService.list(new QueryWrapper<TExerciseInfo>()
