        homeworkModelService.updateById(model);
        //删除作业模板习题
        modelExerciseService.removeById(modelExercise.getId());
        //更新作业模板下的习题类型
        updateExerciseType(modelId, modelExercise.getExerciseType());
        return true;
    }

