     **/
    private void validaChild(List<Integer> childs) {
        childs.forEach(item -> {
            //判断习题是否在使用中，在使用中无法删除
            int count = modelExerciseService.count(new QueryWrapper<TModelExercise>()
                    .eq("exercise_id", item)
                    .eq("delete_flag", 0));
            BusinessResponseEnum.CANNOTDELETEEXERCISE.assertIsFalse(count != 0, item);
        });

    }

