     * @return: 资源类型名称
     **/
    private Map<String, Object> switchResourcesType(String resourcesType) {
        String resTypeName;
        int resType = 0;
        switch (resourcesType) {
            case "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":
            case "application/vnd.ms-excel":
                resTypeName = "表格";
                resType = 1;
                break;
            case "application/vnd.openxmlformats-officedocument.wordprocessingml.document":
            case "application/msword":
                resTypeName = "文档";
                resType = 2;
                break;
            case "application/vnd.ms-powerpoint":
            case "application/vnd.openxmlformats-officedocument.presentationml.presentation":
                resTypeName = "幻灯片";
                resType = 3;
                break;
            case "application/x-zip-compressed":
                resTypeName = "压缩包";
                resType = 4;
                break;
            case "text/plain":
                resTypeName = "文本文档";
                resType = 5;
                break;
            case "text/html":
                resTypeName = "html";
                resType = 6;
                break;
            case "text/xml":
                resTypeName = "xml";
                resType = 7;
                break;
            case "application/x-javascript":
                resTypeName = "js";
                resType = 8;
                break;
            case "video/mp4":
                resTypeName = "视频";
                resType = 9;
                break;
            case "application/pdf":
                resTypeName = "pdf";
                resType = 10;
                break;
            default:
                resTypeName = "";
        }
        if (resourcesType.startsWith("image")) {
            resTypeName = "图片";
            resType = 11;
        }
        if (resourcesType.startsWith("video")
                || resourcesType.startsWith("audio")
                || resourcesType.equals("application/vnd.rn-realmedia-vbr")) {
            resTypeName = "视频";
            resType = 9;
        }
        Map<String, Object> res = new HashMap<>();
        res.put("resType", resType);
        res.put("resTypeName", resTypeName);
        return res;
    }

