    private String getFileRename(String fileName) {
        return fileName.substring(0, fileName.lastIndexOf("."))
                + "_"
                + new SnowflakeIdWorker(0, 0).nextId()
                + fileName.substring(fileName.lastIndexOf("."));
    }

