                tStuHomeworkInfos.add(tStuHomeworkInfo);
            }
        });
        //插入学生作业表
        stuHomeworkMapper.insertBatch(stuHomeworkList);
        //插入学生作业明细表
        stuHomeworkInfoMapper.insertBatch(tStuHomeworkInfos);
    }

