        if (homeworkDistributions.isEmpty()) {
            return;
        }

        //学生作业表集合
        List<TStuHomework> tStuHomeworkList = new ArrayList<>();
        //学生作业明细表集合
        List<TStuHomeworkInfo> tStuHomeworkInfos = new ArrayList<>();
