        //查询目录列表
        List<CourseCatalogue> courseCataloguesList = getCatalogueList(courseId, classId);
        List<CourseCatalogue> collect = null;
        //所有任务数
        AtomicInteger stuAllTaskNum = new AtomicInteger();
        //完成任务数
