            downMove(collect, courseCatalogue, sortNum);
        }
        //更新到数据库
        int updateCatalogue = courseCatalogueMapper.updateById(courseCatalogue);
        logger.error("updateNum={},updateCatalogue={}", updateNum, updateCatalogue);
